#!/bin/bash
# Local build script for Fluidity Marine Astro website
# Generated by local task farm — qwen2.5-coder:7b

set -e

# Change directory
cd /home/aaron-evans/src/fluidity-marine-modern/ || { echo "Failed to cd to project directory"; exit 1; }

# Install dependencies if node_modules is missing
if [ ! -d "node_modules" ]; then
    npm install || { echo "npm install failed"; exit 1; }
fi

# Build the site
npm run build || { echo "Build failed"; exit 1; }

# Copy built output to ~/www/fluidity-local/
mkdir -p ~/www/fluidity-local/
cp -r dist/* ~/www/fluidity-local/ || { echo "Copy failed"; exit 1; }

# Create index.html wrapper
cat <<EOF > ~/www/index.html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Fluidity Marine Modern</title>
    <link rel="stylesheet" href="/fluidity-local/main.css">
</head>
<body>
    <iframe src="/fluidity-local/index.html" width="100%" height="100vh" frameborder="0"></iframe>
</body>
</html>
EOF

# Echo success message
echo "Site built successfully. Open file://$HOME/www/index.html to view."
